parameters.jsonBody:
={{ JSON.stringify({
  model: 'claude-sonnet-5',
  max_tokens: 2000,
  system: $vars.AGENT_SYSTEM_PROMPT,
  messages: [{ role: 'user', content: `Task: post call debrief

Inputs:
contact: ${$json['Who was the call with']}
current_stage: ${$json['Current pipeline stage']}
transcript: ${$json['Transcript or notes']}

Produce exactly three sections with these headings, separated by --- lines:
Call Summary
---
CRM Update
(include: proposed stage [one of Prospect/Lead/MQL/SQL/Deal/Customer], next action, next action due date, and the note to log)
---
Follow-up Draft` }]
}) }}

parameters.jsCode:
const text = $input.first().json.content?.[0]?.text ?? '';
const parts = text.split(/\n-{3,}\n/);
const clean = (s, heading) => (s ?? '').replace(new RegExp('^\\s*' + heading + '\\s*:?\\s*', 'i'), '').trim();
const crm = clean(parts[1], 'CRM Update');
const stageMatch = crm.match(/stage\s*[:\-]?\s*(Prospect|Lead|MQL|SQL|Deal|Customer)/i);
return [{ json: {
  contact: $('Call ended (form)').first().json['Who was the call with'],
  call_summary: clean(parts[0], 'Call Summary'),
  crm_update: crm,
  proposed_stage: stageMatch ? stageMatch[1] : $('Call ended (form)').first().json['Current pipeline stage'],
  follow_up_draft: clean(parts[2], 'Follow-up Draft'),
} }];

parameters.message:
={{ $json.follow_up_draft + '

—
Staged for your approval — nothing has been sent. [orion-self-install v0.1.0]' }}

parameters.jsonBody:
={{ JSON.stringify({ data: { title: 'Call debrief — ' + $now.format('yyyy-MM-dd'), format: 'plaintext', content: $('Split sections').first().json.call_summary + '

CRM update applied:
' + $('Split sections').first().json.crm_update } }) }}
